import { hashPassword } from '@api/lib/auth/hashPassword'
import { bypassDb as db } from '@api/lib/db'
import { scenario } from '@api/lib/testing'
import { describe, expect } from 'vitest'

describe('Authentication Route Tests', () => {
  scenario('should return success message on valid login', async ({ app }) => {
    const email = 'test@example.com'
    const [hashedPassword, salt] = hashPassword('password')

    await db.user.create({
      data: {
        hashedPassword: hashedPassword,
        salt: salt,
        email: email,
        firstName: 'user',
        lastName: 'user',
        verificationToken: null,
        activeStart: new Date(),
      },
    })

    const response = await app.inject({
      method: 'POST',
      url: 'api/auth/login?redirect=/home',
      payload: {
        email: email,
        password: 'password',
      },
    })

    expect(response.statusCode).toBe(200)
    expect(JSON.parse(response.body)).toEqual({ success: true, message: 'Successfully logged in.' })
  })

  scenario('should return unauthorized message on invalid login', async ({ app }) => {
    const email = 'test@example.com'
    const [hashedPassword, salt] = hashPassword('password')

    await db.user.create({
      data: {
        hashedPassword: hashedPassword,
        salt: salt,
        email: email,
        firstName: 'user',
        lastName: 'user',
        verificationToken: null,
        activeStart: new Date(),
      },
    })
    const response = await app.inject({
      method: 'POST',
      url: 'api/auth/login',
      payload: {
        email: 'invalid@example.com',
        password: 'wrongpassword',
      },
    })

    expect(response.statusCode).toBe(401)
    expect(response.body).toEqual('Unauthorized')
  })
})
